                f.write(f"Path: {doc['path']}\n")
                f.write(f"Text Sample: {doc['text']}\n")
                f.write("Child Elements:\n")
                for child in doc['childElements']:
                    f.write(f"  - {child['tag']} ({child['classes']}): {child['text']}\n")
