                f.write(f"ID: {sample['id']}\n")
                f.write(f"Classes: {sample['classes']}\n")
                f.write(f"Path: {sample['path']}\n")
                f.write(f"Text: {sample['text']}\n\n")

        print(f"Page structure analysis saved to {filename}")
        return analysis_data

    except Exception as e:
        print(f"Error analyzing page structure: {str(e)}")
        return None

def extract_page_content(driver, llm_config, filename=None):
    """
    Extract page content and save to file, preserving format and distinguishing between generated content and UI elements

    Args:
        driver: Selenium WebDriver instance
        llm_config: Configuration for the specific LLM
        filename: Output filename (optional)

    Returns:
        Dict containing page content
    """
    if filename is None:
        filename = f"{llm_config['name'].lower()}_content.txt"

    try:
        # Get page title
        title = driver.title

        # Create JavaScript extraction script that adapts to the LLM's structure
        js_script = """
        function getFormattedContent(config) {
            // Store content
            let content = {
                conversationTurns: [],
                uiElements: []
            };

            // Find the main content area using flexible selectors
            const mainContentSelectors = [
                'main', 
                'article',
                'div.flex-1.flex.flex-col.gap-3',
                '.conversation-container',
                '.chat-container',
                '.main-content',
                'div[role="main"]'
            ];

            let mainContentArea = null;

            for (const selector of mainContentSelectors) {
                const element = document.querySelector(selector);
                if (element) {
                    mainContentArea = element;
                    break;
                }
            }

            if (!mainContentArea) {
                return { error: "Cannot find main content area" };
            }

            // Try to find conversation elements with user queries and assistant responses
            // First, look for user query elements
            const userQuerySelector = config.content_patterns.user_query || '.user-message';
            const userQueries = document.querySelectorAll(userQuerySelector);

            const assistantResponseSelector = config.content_patterns.response_container || '.assistant-message';
            const assistantResponses = document.querySelectorAll(assistantResponseSelector);

            const codeBlockSelector = config.content_patterns.code_block || 'pre';

            // Check if we found structured conversation elements
            if (userQueries.length > 0 || assistantResponses.length > 0) {
                // Try to match user queries with their responses
                // First approach: Look for alternating patterns
                let currentTurn = null;
                let userElements = Array.from(userQueries);
                let assistantElements = Array.from(assistantResponses);

                // If the counts don't match, try to pair them correctly by position
                if (userElements.length >= assistantElements.length) {
                    // Pair elements based on position
                    for (let i = 0; i < userElements.length; i++) {
                        const userElement = userElements[i];

                        // Extract user query text
                        let queryText = userElement.textContent.trim();

                        // Clean up common patterns
                        queryText = queryText.replace(/Edit$/, '').trim();
                        queryText = queryText.replace(/^[A-Z]\\s*/, '').trim();

                        // Create new turn
                        currentTurn = {
                            query: queryText,
                            responses: [],
                            codeBlocks: [],
                            documents: [],
                            codeExplanations: []
                        };

                        // Find corresponding assistant response (if any)
                        if (i < assistantElements.length) {
                            const assistantElement = assistantElements[i];
                            processAssistantResponse(assistantElement, currentTurn);
                        }

                        // Add turn to results
                        content.conversationTurns.push(currentTurn);
                    }
                } else {
                    // If we have more assistant responses than user queries, something is wrong
                    // Just try to extract what we can
                    console.warn("More assistant responses than user queries found. Extraction may be incomplete.");

                    // First pass: handle paired exchanges
                    for (let i = 0; i < userElements.length; i++) {
                        const userElement = userElements[i];

                        // Extract user query text
                        let queryText = userElement.textContent.trim();

                        // Clean up common patterns
                        queryText = queryText.replace(/Edit$/, '').trim();
                        queryText = queryText.replace(/^[A-Z]\\s*/, '').trim();

                        // Create new turn
                        currentTurn = {
                            query: queryText,
                            responses: [],
                            codeBlocks: [],
                            documents: [],
                            codeExplanations: []
                        };

                        // Find corresponding assistant response
                        if (i < assistantElements.length) {
                            const assistantElement = assistantElements[i];
                            processAssistantResponse(assistantElement, currentTurn);
                        }

                        // Add turn to results
                        content.conversationTurns.push(currentTurn);
                    }

                    // Second pass: add remaining assistant responses as standalone entries
                    for (let i = userElements.length; i < assistantElements.length; i++) {
                        const assistantElement = assistantElements[i];

                        // Create new turn with empty query
                        currentTurn = {
                            query: "[Query not detected]",
                            responses: [],
                            codeBlocks: [],
                            documents: [],
                            codeExplanations: []
                        };

                        // Process the response
                        processAssistantResponse(assistantElement, currentTurn);

                        // Add turn to results
                        content.conversationTurns.push(currentTurn);
                    }
                }

            } else {
                // If we couldn't find structured conversation elements, try to extract content more generically

                // Get all direct children of main content area, they might be conversation turns
                const conversationElements = Array.from(mainContentArea.children);

                // Initialize variable to track current turn
                let currentTurn = null;

                for (const element of conversationElements) {
                    // Try different heuristics to detect if this is a user query
                    const isUserQuery = 
                        element.classList.contains('user-message') || 
                        element.classList.contains('query') ||
                        element.getAttribute('data-message-author-role') === 'user' ||
                        element.querySelector('.bg-bg-300') ||  // Claude-specific
                        element.textContent.includes('You:') ||
                        element.textContent.includes('User:');

                    if (isUserQuery) {
                        // If there's a previous turn, add it to results
                        if (currentTurn) {
                            content.conversationTurns.push(currentTurn);
                        }

                        // Extract user query text
                        let queryText = element.textContent.trim();

                        // Clean up common patterns
                        queryText = queryText.replace(/Edit$/, '').trim();
                        queryText = queryText.replace(/You:\\s*/, '').trim();
                        queryText = queryText.replace(/User:\\s*/, '').trim();
                        queryText = queryText.replace(/^[A-Z]\\s*/, '').trim();

                        // Create new turn
                        currentTurn = {
                            query: queryText,
                            responses: [],
                            codeBlocks: [],
                            documents: [],
                            codeExplanations: []
                        };
                    } else {
                        // If no current turn, skip
                        if (!currentTurn) continue;

                        // Check if this is an assistant response
                        const isAssistantResponse = 
                            element.classList.contains('assistant-message') ||
                            element.classList.contains('response') ||
                            element.getAttribute('data-message-author-role') === 'assistant' ||
                            element.querySelector('.font-claude-message') ||  // Claude-specific
                            element.querySelector('[class*="tracking"]') ||   // Claude-specific
                            element.textContent.includes('Assistant:') ||
                            element.textContent.includes('AI:');

                        if (isAssistantResponse) {
                            processAssistantResponse(element, currentTurn);
                        }
                    }
                }

                // Add the last turn if it exists
                if (currentTurn) {
                    content.conversationTurns.push(currentTurn);
                }
            }

            // Process assistant response element to extract responses, code blocks, etc.
            function processAssistantResponse(element, turn) {
                // 1. Find code blocks
                const codeBlocks = element.querySelectorAll(codeBlockSelector);
                for (const codeBlock of codeBlocks) {
                    // Get code language
                    let language = '';
                    const codeElement = codeBlock.querySelector('code');
                    if (codeElement && codeElement.className) {
                        const match = codeElement.className.match(/language-([a-zA-Z0-9]+)/);
                        if (match) {
                            language = match[1];
                        }
                    }

                    // Get code text
                    let codeText = codeBlock.textContent || "";

                    // Remove "Copy" and language identifier
                    codeText = codeText.replace(/^(python|javascript|html|css|json)\\s*Copy\\s*/i, '');

                    // Add code block to current turn
                    if (codeText.trim()) {
                        turn.codeBlocks.push({
                            language: language || 'python', // Default to python
                            code: codeText
                        });
                    }
                }

                // 2. Find document references
                const docButtons = element.querySelectorAll('button[class*="font-styrene"][class*="border-0"]');
                for (const docButton of docButtons) {
                    // Extract document title
                    const docTitle = docButton.textContent.replace(/Click to open document.*$/, '').trim();

                    // Try to find document content
                    let docContent = [];

                    // Check for sidebar with document content
                    const sidebarContent = document.querySelector('div[class*="fixed"][class*="right-0"][class*="flex"][class*="w-full"]');
                    if (sidebarContent) {
                        // Extract paragraphs from sidebar
                        const docTextElements = sidebarContent.querySelectorAll('p');
                        for (const textEl of docTextElements) {
                            docContent.push(textEl.textContent.trim());
                        }
                    }

                    // Add document to current turn
                    if (docTitle) {
                        turn.documents.push({
                            title: docTitle,
                            content: docContent
                        });
                    }
                }

                // 3. Extract code explanations and usage instructions
                let codeExplanations = [];

                // Look for lists (ordered and unordered)
                const listItems = element.querySelectorAll('ol li, ul li');
                for (const item of listItems) {
                    // Check not inside code block
                    if (!item.closest('pre')) {
                        codeExplanations.push(item.textContent.trim());
                    }
                }

                // If list items found, add as code explanations
                if (listItems.length > 0) {
                    const orderedLists = element.querySelectorAll('ol');
                    for (const list of orderedLists) {
                        // Check not inside code block
                        if (!list.closest('pre')) {
                            codeExplanations.push(list.textContent.trim());
                        }
                    }

                    const unorderedLists = element.querySelectorAll('ul');
                    for (const list of unorderedLists) {
                        // Check not inside code block
                        if (!list.closest('pre')) {
                            codeExplanations.push(list.textContent.trim());
                        }
                    }
                }

                // Look for paragraphs and divs that might contain usage instructions
                const explanationParagraphs = element.querySelectorAll('p, div');
                for (const para of explanationParagraphs) {
                    const text = para.textContent.trim();

                    // Specific keywords for paragraphs not in code blocks
                    if ((text.includes('To use this code') || 
                        text.includes('Install') || 
                        text.includes('Set your API') || 
                        text.includes('Run the script') ||
                        text.includes('adjust parameters') ||
                        text.includes('This demo shows')) && 
                        !para.closest('pre') && 
                        !para.querySelector('pre') &&
                        !text.includes('can make mistakes')) {

                        // Skip if already added (avoid duplicates)
                        if (!codeExplanations.includes(text)) {
                            codeExplanations.push(text);
                        }
                    }
                }

                // Add to current turn
                turn.codeExplanations = codeExplanations;

                // 4. More comprehensive capture of explanation text
                // Create temp container to hold all content, filter out code areas
                const tempDiv = document.createElement('div');
                tempDiv.innerHTML = element.innerHTML;

                // Remove all code blocks to get remaining text
                const codeToRemove = tempDiv.querySelectorAll('pre');
                for (const code of codeToRemove) {
                    if (code.parentNode) {
                        code.parentNode.removeChild(code);
                    }
                }

                // Look for specific paragraph text patterns
                const remainingText = tempDiv.textContent;
                const usageMatch = remainingText.match(/To use this code:([\\s\\S]*?)(?=\\n\\n|$)/);
                if (usageMatch && usageMatch[1]) {
                    const usageText = usageMatch[1].trim();
                    if (usageText && !codeExplanations.includes(usageText)) {
                        codeExplanations.push("To use this code:" + usageText);
                    }
                }

                // Look for other key explanation paragraphs
                const demoMatch = remainingText.match(/This demo shows([\\s\\S]*?)(?=\\n\\n|$)/);
                if (demoMatch && demoMatch[0]) {
                    const demoText = demoMatch[0].trim();
                    if (demoText && !codeExplanations.includes(demoText)) {
                        codeExplanations.push(demoText);
                    }
                }

                // 5. Extract response text (excluding code blocks, buttons, and captured explanations)
                let responseText = '';

                // Find all paragraph elements
                const allParagraphs = element.querySelectorAll('p');
                for (const para of allParagraphs) {
                    // Exclude paragraphs in code blocks, document reference buttons, and obvious explanation text
                    const paraText = para.textContent.trim();
                    if (!para.closest('pre') && 
                        !para.closest('button') && 
                        !paraText.includes('To use this code') &&
                        !paraText.includes('This demo shows') &&
                        !paraText.includes('can make mistakes')) {

                        responseText += paraText + '\\n\\n';
                    }
                }

                // If no paragraphs found or text empty, try to extract from main element
                if (!responseText.trim()) {
                    // Copy content
                    const tempTextDiv = document.createElement('div');
                    tempTextDiv.innerHTML = element.innerHTML;

                    // Remove code blocks, buttons, and other UI elements
                    const elementsToRemove = [
                        ...tempTextDiv.querySelectorAll('pre'),
                        ...tempTextDiv.querySelectorAll('button'),
                        ...tempTextDiv.querySelectorAll('ol'),
                        ...tempTextDiv.querySelectorAll('ul')
                    ];

                    for (const el of elementsToRemove) {
                        if (el.parentNode) {
                            el.parentNode.removeChild(el);
                        }
                    }

                    // Remove UI element text
                    responseText = tempTextDiv.textContent.trim()
                        .replace(/Retry/g, '')
                        .replace(/Copy/g, '')
                        .replace(/Edit/g, '')
                        .replace(/can make mistakes. Please double-check responses./g, '')
                        .trim();
                }

                // Remove excessive empty lines
                responseText = responseText.replace(/\\n{3,}/g, '\\n\\n');

                // Add to current turn's responses
                if (responseText.trim()) {
                    turn.responses.push(responseText);
                }
            }

            // Collect page header information as UI elements
            const headerElement = document.querySelector('header');
            if (headerElement) {
                content.uiElements.push({
                    type: 'header',
                    text: headerElement.textContent.trim()
                });
            }

            // Collect page footer disclaimers
            const disclaimerElement = document.querySelector('div[class*="can make mistakes"]');
            if (disclaimerElement) {
                content.uiElements.push({
                    type: 'disclaimer',
                    text: disclaimerElement.textContent.trim()
                });
            }

            return content;
        }

        return getFormattedContent(config);
        """

        # Convert LLM config to JSON for JavaScript
        config_json = json.dumps(llm_config)

        # Execute JavaScript to extract content
        content_data = driver.execute_script(f"const config = {config_json};\n" + js_script)

        # Check for errors
        if isinstance(content_data, dict) and 'error' in content_data:
            print(f"JavaScript execution error: {content_data['error']}")
            return None

        # Save structured content to file
        with open(filename, 'w', encoding='utf-8') as f:
            f.write(f"Page Title: {title}\n\n")

            f.write("=" * 80 + "\n")
            f.write("Conversation Content:\n")
            f.write("=" * 80 + "\n\n")

            # Write conversation turns
            for i, turn in enumerate(content_data['conversationTurns']):
                f.write(f"Turn {i+1}:\n")
                f.write(f"User Query: {turn['query']}\n\n")

                f.write(f"{llm_config['name']} Response:\n")
                for response in turn['responses']:
                    f.write(f"{response}\n\n")

                # Write document content
                for j, doc in enumerate(turn['documents']):
                    f.write(f"Document {j+1}: {doc['title']}\n")
                    for content in doc['content']:
                        f.write(f"{content}\n")
                    f.write("\n")

                # Write code blocks
                for j, code_block in enumerate(turn['codeBlocks']):
                    f.write(f"Code Block {j+1}")
                    if code_block['language']:
                        f.write(f" ({code_block['language']}):\n")
                    else:
                        f.write(":\n")

                    # Preserve original format for code
                    f.write(f"{code_block['code']}\n\n")

                # Write code explanations
                if turn['codeExplanations'] and len(turn['codeExplanations']) > 0:
                    f.write("Code Explanations:\n")
                    for explanation in turn['codeExplanations']:
                        f.write(f"{explanation}\n\n")

                f.write("-" * 80 + "\n\n")

            f.write("\n" + "=" * 80 + "\n")
            f.write("UI Elements (Page Inherent Content):\n")
            f.write("=" * 80 + "\n\n")

            # Write UI elements
            for i, element in enumerate(content_data['uiElements']):
                f.write(f"UI Element {i+1} ({element['type']}):\n{element['text']}\n\n")

        # Save structured content as JSON
        json_filename = filename.rsplit('.', 1)[0] + '.json'
        with open(json_filename, 'w', encoding='utf-8') as f:
            json.dump(content_data, f, ensure_ascii=False, indent=2)

        print(f"Page content saved to {filename}")
        print(f"Structured content saved to {json_filename}")

        return content_data

    except Exception as e:
        print(f"Error extracting page content: {str(e)}")
        return None

def create_output_dir(llm_name):
    """Create output directory for specific LLM"""
    output_dir = f"llm_page_analysis_{llm_name.lower()}"
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)
    return output_dir

def detect_llm_provider(driver):
    """
    Detect which LLM provider's interface we're looking at

    Args:
        driver: Selenium WebDriver instance

    Returns:
        str: LLM provider key ('claude', 'chatgpt', 'bard', etc.) or 'generic'
    """
    try:
        # Check URL for obvious patterns
        current_url = driver.current_url.lower()

        if 'claude.ai' in current_url:
            return 'claude'
        elif 'chat.openai.com' in current_url:
            return 'chatgpt'
        elif 'gemini.google.com' in current_url or 'bard.google.com' in current_url:
            return 'bard'

        # Check page content for LLM-specific elements
        page_source = driver.page_source.lower()
        page_title = driver.title.lower()

        if 'claude' in page_title or 'anthropic' in page_title or 'claude' in page_source:
            return 'claude'
        elif 'chatgpt' in page_title or 'openai' in page_title or 'gpt' in page_source:
            return 'chatgpt'
        elif 'gemini' in page_title or 'bard' in page_title or 'google ai' in page_title:
            return 'bard'

        # If still not detected, try browser structure analysis
        for llm_key, config in LLM_CONFIGS.items():
            if llm_key == 'generic':
                continue

            # Check if selectors match
            matches = 0
            for selector_key, selector in config['selectors'].items():
                try:
                    elements = driver.find_elements("css selector", selector)
                    if elements:
                        matches += 1
                except:
                    continue

            # If we found multiple matches, this is likely our LLM
            if matches >= 2:
                return llm_key

        # Default to generic if we can't identify
        return 'generic'
    except Exception as e:
        print(f"Error detecting LLM provider: {str(e)}")
        return 'generic'

def main():
    """Main function to run the LLM page analyzer"""
    parser = argparse.ArgumentParser(description='Analyze LLM web interfaces')
    parser.add_argument('--url', type=str, help='URL pattern to find (e.g., "claude.ai", "chat.openai.com")', default=None)
    parser.add_argument('--llm', type=str, help='LLM provider (claude, chatgpt, bard, or generic)', default=None)
    parser.add_argument('--browser-port', type=int, help='Chrome debugging port', default=54805)
    parser.add_argument('--chromedriver', type=str, help='Path to chromedriver', default=None)
    parser.add_argument('--output-dir', type=str, help='Output directory', default=None)
    args = parser.parse_args()

    try:
        # Set up Chrome driver
        chrome_options = Options()
        chrome_options.add_experimental_option("debuggerAddress", f"127.0.0.1:{args.browser_port}")

        if args.chromedriver:
            service = Service(args.chromedriver)
        else:
            # Try to use webdriver-manager or look for chromedriver in common locations
            try:
                service = Service(ChromeDriverManager().install())
            except Exception as e:
                print(f"Error using ChromeDriverManager: {e}")

                # Check common locations
                common_paths = [
                    "/usr/local/bin/chromedriver",
                    "/usr/bin/chromedriver",
                    "~/.local/share/undetected_chromedriver/undetected_chromedriver",
                    "/home/endian/.local/share/undetected_chromedriver/undetected_chromedriver",  # From original code
                ]

                for path in common_paths:
                    expanded_path = os.path.expanduser(path)
                    if os.path.exists(expanded_path):
                        service = Service(expanded_path)
                        break
                else:
                    raise Exception("Could not find chromedriver. Please specify path with --chromedriver.")

        driver = webdriver.Chrome(service=service, options=chrome_options)

        # Create BrowserSession
        class SimpleBrowserService:
            def __init__(self):
                self.screenshots_dir = None
                self.cookies_manager = None

        browser_service = SimpleBrowserService()
        browser_session = BrowserSession(driver, service, browser_service)

        # If URL pattern is provided, find and switch to that tab
        if args.url:
            print(f"Looking for tab containing {args.url}...")
            loop = asyncio.get_event_loop()
            target_handle = loop.run_until_complete(get_tab_by_url_pattern(browser_session, args.url))

            if target_handle:
                print(f"Found tab containing {args.url}: {target_handle}")
                # Switch to tab
                loop.run_until_complete(browser_session.switch_to_tab(target_handle))
            else:
                print(f"No tab found containing {args.url}")
                return None

        # Print all tabs info (for debugging)
        loop = asyncio.get_event_loop()
        all_handles = loop.run_until_complete(browser_session.get_all_tabs())
        print(f"All tabs: {all_handles}")

        # Detect LLM provider if not specified
        llm_key = args.llm if args.llm else detect_llm_provider(driver)
        print(f"Detected LLM provider: {llm_key}")

        # Get LLM config
        if llm_key in LLM_CONFIGS:
            llm_config = LLM_CONFIGS[llm_key]
        else:
            print(f"Unknown LLM provider: {llm_key}. Using generic configuration.")
            llm_config = LLM_CONFIGS['generic']
            llm_config['name'] = llm_key.capitalize()

        # Create output directory
        output_dir = args.output_dir if args.output_dir else create_output_dir(llm_config['name'])
        print(f"Output directory: {output_dir}")

        # Extract page content
        print("\nExtracting page content...")
        content_file = os.path.join(output_dir, f"{llm_config['name'].lower()}_content.txt")
        extract_page_content(driver, llm_config, content_file)

        # Analyze page structure
        print("\nAnalyzing page structure...")
        structure_file = os.path.join(output_dir, f"{llm_config['name'].lower()}_structure.txt")
        analyze_page_structure(driver, llm_config, structure_file)

