                    if (!aHasVisible && bHasVisible) return 1;

                    // Prefer elements with more text content (likely responses)
                        const aTextLength = a.test.elements.reduce((sum, el) => sum + el.text.length, 0);
                        const bTextLength = b.test.elements.reduce((sum, el) => sum + el.text.length, 0);
                        return bTextLength - aTextLength;
                    });
                }

            // Return all discovered selectors
            return {
                newChatSelectors: findNewChatButton(),
                fileUploadSelectors: findFileUploadElements(),
                messageInputSelectors: findMessageInput(),
                sendButtonSelectors: findSendButton(),
                responseContainerSelectors: findResponseContainer()
            };
        }

        return findBestSelectors(targetConfig);
        """

        # Convert LLM config to JSON for JavaScript
        config_json = json.dumps(llm_config)

        # Execute the JavaScript to analyze selectors
